<?php

namespace Jurager\Teams\Database\Factories;

use Illuminate\Database\Eloquent\Factories\Factory;
use Illuminate\Database\Eloquent\Model;
use Jurager\Teams\Facades\Teams;

class TeamFactory extends Factory
{
    /**
     * Get the name of the model that is generated by the factory.
     */
    public function modelName(): string
    {
        return Teams::model('team');
    }

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'user_id' => Teams::model('user')::factory(),
            'name' => fake()->company(),
        ];
    }

    /**
     * Add new users to the team with the given role, creating the role when it is missing.
     */
    public function members(int $count = 1, string $role = 'member'): static
    {
        return $this->afterCreating(function (Model $team) use ($count, $role) {
            $role = $team->roles()->firstOrCreate(['code' => $role]);

            foreach (Teams::model('user')::factory()->count($count)->create() as $user) {
                $team->add($user)->as($role);
            }
        });
    }
}
